-- Database field descriptions; optional COMMENT metadata, no structural changes.
BEGIN;
COMMENT ON TABLE ktc.app_user IS 'External identity mapping and application account flags.';
COMMENT ON TABLE ktc.project IS 'Top-level construction project, ownership and archive state.';
COMMENT ON TABLE ktc.project_user IS 'One retained row for each user and project pair.';
COMMENT ON TABLE ktc.drawing IS 'Validated immutable PDF metadata; bytes live in object storage.';
COMMENT ON TABLE ktc.drawing_page IS 'One row per PDF page, with normalized-coordinate reference dimensions.';
COMMENT ON TABLE ktc.punch_item IS 'Deficiency details, immutable page anchor, current assignment and workflow state.';
COMMENT ON TABLE ktc.comment IS 'Text evidence with author attribution.';
COMMENT ON TABLE ktc.photo IS 'Metadata for images attached to punch items.';
COMMENT ON TABLE ktc.markup IS 'Validated annotations on a drawing page, optionally linked to an item.';
COMMENT ON TABLE ktc.export_job IS 'Queued project export requests and verified output metadata.';
COMMENT ON TABLE ktc.punch_item_event IS 'Append-only records of item creation, status, assignment and revision changes.';
COMMENT ON TABLE ktc.schema_migration IS 'Technical record of applied database migrations.';
COMMENT ON COLUMN ktc.app_user.user_id IS 'Account identifier used in membership and attribution.';
COMMENT ON COLUMN ktc.app_user.auth_issuer IS 'Verified identity provider namespace. Together with auth_subject, uniquely identifies the external account.';
COMMENT ON COLUMN ktc.app_user.auth_subject IS 'Immutable identity provider subject. Never export or accept it as a client-selected identity.';
COMMENT ON COLUMN ktc.app_user.display_name IS 'User-facing name shown on assignments and comments.';
COMMENT ON COLUMN ktc.app_user.email IS 'Optional email address. Unique ignoring case when present.';
COMMENT ON COLUMN ktc.app_user.is_active IS 'Whether this account or project membership currently permits access.';
COMMENT ON COLUMN ktc.app_user.can_create_projects IS 'Operator-granted permission to create projects and become their first administrator.';
COMMENT ON COLUMN ktc.app_user.created_at IS 'Creation instant with time zone; database generated.';
COMMENT ON COLUMN ktc.app_user.updated_at IS 'Last change instant with time zone; set automatically by authorized writes.';
COMMENT ON COLUMN ktc.comment.comment_id IS 'Unique text-comment identifier.';
COMMENT ON COLUMN ktc.comment.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.comment.punch_item_id IS 'Punch-item identifier. Optional only for a drawing-level markup.';
COMMENT ON COLUMN ktc.comment.author_user_id IS 'Comment author, derived from the verified actor and linked to project membership.';
COMMENT ON COLUMN ktc.comment.body IS 'Nonblank comment text, at most 10000 characters.';
COMMENT ON COLUMN ktc.comment.created_at IS 'Creation instant with time zone; database generated.';
COMMENT ON COLUMN ktc.comment.updated_at IS 'Last change instant with time zone; set automatically by authorized writes.';
COMMENT ON COLUMN ktc.drawing.drawing_id IS 'Immutable PDF drawing identifier. A revised PDF receives a new identifier.';
COMMENT ON COLUMN ktc.drawing.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.drawing.filename IS 'Original display filename. Never used directly to construct a storage path.';
COMMENT ON COLUMN ktc.drawing.storage_ref IS 'Private object key. Must follow the project and record UUID path pattern.';
COMMENT ON COLUMN ktc.drawing.content_type IS 'Validated MIME type. PDF for drawings; JPEG, PNG or WebP for photos.';
COMMENT ON COLUMN ktc.drawing.size_bytes IS 'Verified object length in bytes; positive integer.';
COMMENT ON COLUMN ktc.drawing.sha256 IS 'SHA-256 digest of stored bytes, exactly 64 lowercase hexadecimal characters.';
COMMENT ON COLUMN ktc.drawing.page_count IS 'Positive PDF page count verified during parsing. All page records must exist at commit.';
COMMENT ON COLUMN ktc.drawing.uploaded_by IS 'Project member who uploaded the file; set from the verified actor.';
COMMENT ON COLUMN ktc.drawing.created_at IS 'Creation instant with time zone; database generated.';
COMMENT ON COLUMN ktc.drawing_page.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.drawing_page.drawing_id IS 'Immutable PDF drawing identifier. A revised PDF receives a new identifier.';
COMMENT ON COLUMN ktc.drawing_page.page_number IS 'One-based page number. Must identify an existing page of the same project drawing.';
COMMENT ON COLUMN ktc.drawing_page.width_points IS 'Unrotated PDF CropBox width in points, with 3 fractional digits; positive and finite.';
COMMENT ON COLUMN ktc.drawing_page.height_points IS 'Unrotated PDF CropBox height in points, with 3 fractional digits; positive and finite.';
COMMENT ON COLUMN ktc.drawing_page.rotation IS 'Intrinsic page rotation in degrees: 0, 90, 180 or 270.';
COMMENT ON COLUMN ktc.export_job.export_id IS 'Unique asynchronous export job identifier, also used in the archive object key.';
COMMENT ON COLUMN ktc.export_job.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.export_job.requested_by IS 'Authorized administrator or reviewer who requested the project export.';
COMMENT ON COLUMN ktc.export_job.format IS 'Portable package format identifier. Version 1 supports zip_v1.';
COMMENT ON COLUMN ktc.export_job.status IS 'Current workflow state, constrained to the corresponding enum and transition rules.';
COMMENT ON COLUMN ktc.export_job.storage_ref IS 'Private object key. Must follow the project and record UUID path pattern.';
COMMENT ON COLUMN ktc.export_job.size_bytes IS 'Verified object length in bytes; positive integer.';
COMMENT ON COLUMN ktc.export_job.sha256 IS 'SHA-256 digest of stored bytes, exactly 64 lowercase hexadecimal characters.';
COMMENT ON COLUMN ktc.export_job.error_message IS 'Sanitized failure reason for a failed export, at most 2000 characters.';
COMMENT ON COLUMN ktc.export_job.created_at IS 'Creation instant with time zone; database generated.';
COMMENT ON COLUMN ktc.export_job.started_at IS 'Worker claim time. NULL while queued.';
COMMENT ON COLUMN ktc.export_job.completed_at IS 'Completion instant for succeeded or failed jobs. NULL before completion.';
COMMENT ON COLUMN ktc.export_job.expires_at IS 'Download expiry for successful archives. The completion function sets seven days.';
COMMENT ON COLUMN ktc.markup.markup_id IS 'Unique graphical-annotation identifier.';
COMMENT ON COLUMN ktc.markup.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.markup.drawing_id IS 'Immutable PDF drawing identifier. A revised PDF receives a new identifier.';
COMMENT ON COLUMN ktc.markup.page_number IS 'One-based page number. Must identify an existing page of the same project drawing.';
COMMENT ON COLUMN ktc.markup.punch_item_id IS 'Punch-item identifier. Optional only for a drawing-level markup.';
COMMENT ON COLUMN ktc.markup.markup_type IS 'Primitive type: pin, rectangle, line, arrow, freehand or text.';
COMMENT ON COLUMN ktc.markup.geometry_json IS 'Version 1 geometry object with normalized points; validated shape and at most 262144 serialized bytes.';
COMMENT ON COLUMN ktc.markup.created_by IS 'User who created the record; runtime triggers derive this from the verified actor.';
COMMENT ON COLUMN ktc.markup.created_at IS 'Creation instant with time zone; database generated.';
COMMENT ON COLUMN ktc.markup.updated_at IS 'Last change instant with time zone; set automatically by authorized writes.';
COMMENT ON COLUMN ktc.photo.photo_id IS 'Unique photo identifier, used in its private object key.';
COMMENT ON COLUMN ktc.photo.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.photo.punch_item_id IS 'Punch-item identifier. Optional only for a drawing-level markup.';
COMMENT ON COLUMN ktc.photo.uploaded_by IS 'Project member who uploaded the file; set from the verified actor.';
COMMENT ON COLUMN ktc.photo.filename IS 'Original display filename. Never used directly to construct a storage path.';
COMMENT ON COLUMN ktc.photo.storage_ref IS 'Private object key. Must follow the project and record UUID path pattern.';
COMMENT ON COLUMN ktc.photo.content_type IS 'Validated MIME type. PDF for drawings; JPEG, PNG or WebP for photos.';
COMMENT ON COLUMN ktc.photo.size_bytes IS 'Verified object length in bytes; positive integer.';
COMMENT ON COLUMN ktc.photo.sha256 IS 'SHA-256 digest of stored bytes, exactly 64 lowercase hexadecimal characters.';
COMMENT ON COLUMN ktc.photo.caption IS 'Optional descriptive photo caption, at most 1000 characters.';
COMMENT ON COLUMN ktc.photo.created_at IS 'Creation instant with time zone; database generated.';
COMMENT ON COLUMN ktc.project.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.project.name IS 'Human-readable project name; must contain non-whitespace text.';
COMMENT ON COLUMN ktc.project.description IS 'Detailed description. At most 10000 characters; required and nonblank on a punch item.';
COMMENT ON COLUMN ktc.project.created_by IS 'Account that created the project; set by create_project.';
COMMENT ON COLUMN ktc.project.created_at IS 'Creation instant with time zone; database generated.';
COMMENT ON COLUMN ktc.project.updated_at IS 'Last change instant with time zone; set automatically by authorized writes.';
COMMENT ON COLUMN ktc.project.archived_at IS 'NULL for an active project. A timestamp makes project content read-only; administrators can restore it.';
COMMENT ON COLUMN ktc.project_user.project_user_id IS 'Stable membership record identifier; project and user pair is also unique.';
COMMENT ON COLUMN ktc.project_user.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.project_user.user_id IS 'Account identifier used in membership and attribution.';
COMMENT ON COLUMN ktc.project_user.role IS 'Project-specific permission class: administrator, inspector, contractor or reviewer.';
COMMENT ON COLUMN ktc.project_user.is_active IS 'Whether this account or project membership currently permits access.';
COMMENT ON COLUMN ktc.project_user.joined_at IS 'When this membership was first created. Reactivation preserves it.';
COMMENT ON COLUMN ktc.project_user.updated_at IS 'Last change instant with time zone; set automatically by authorized writes.';
COMMENT ON COLUMN ktc.punch_item.punch_item_id IS 'Punch-item identifier. Optional only for a drawing-level markup.';
COMMENT ON COLUMN ktc.punch_item.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.punch_item.drawing_id IS 'Immutable PDF drawing identifier. A revised PDF receives a new identifier.';
COMMENT ON COLUMN ktc.punch_item.page_number IS 'One-based page number. Must identify an existing page of the same project drawing.';
COMMENT ON COLUMN ktc.punch_item.x_ratio IS 'Horizontal position in the unrotated CropBox, from its left edge; normalized 0 through 1.';
COMMENT ON COLUMN ktc.punch_item.y_ratio IS 'Vertical position in the unrotated CropBox, from its top edge; normalized 0 through 1.';
COMMENT ON COLUMN ktc.punch_item.title IS 'Concise issue title; nonblank and at most 200 characters.';
COMMENT ON COLUMN ktc.punch_item.description IS 'Detailed description. At most 10000 characters; required and nonblank on a punch item.';
COMMENT ON COLUMN ktc.punch_item.status IS 'Current workflow state, constrained to the corresponding enum and transition rules.';
COMMENT ON COLUMN ktc.punch_item.assignee_user_id IS 'Optional current responsible user. Must be an active member of the same project.';
COMMENT ON COLUMN ktc.punch_item.created_by IS 'User who created the record; runtime triggers derive this from the verified actor.';
COMMENT ON COLUMN ktc.punch_item.created_at IS 'Creation instant with time zone; database generated.';
COMMENT ON COLUMN ktc.punch_item.updated_at IS 'Last change instant with time zone; set automatically by authorized writes.';
COMMENT ON COLUMN ktc.punch_item.version IS 'Item revision counter starting at 1. Every update increments it for optimistic concurrency.';
COMMENT ON COLUMN ktc.punch_item_event.event_id IS 'Database-generated bigint audit sequence. Gaps are allowed after rolled-back work.';
COMMENT ON COLUMN ktc.punch_item_event.project_id IS 'Owning project identifier. Included in related foreign keys for project separation.';
COMMENT ON COLUMN ktc.punch_item_event.punch_item_id IS 'Punch-item identifier. Optional only for a drawing-level markup.';
COMMENT ON COLUMN ktc.punch_item_event.actor_user_id IS 'Verified project member responsible for this accepted item change.';
COMMENT ON COLUMN ktc.punch_item_event.action IS 'Either created or updated; set by the item-history trigger.';
COMMENT ON COLUMN ktc.punch_item_event.old_status IS 'Previous workflow state. NULL on creation.';
COMMENT ON COLUMN ktc.punch_item_event.new_status IS 'Workflow state after the accepted change.';
COMMENT ON COLUMN ktc.punch_item_event.old_assignee IS 'Previous assignee; nullable. References retained project membership.';
COMMENT ON COLUMN ktc.punch_item_event.new_assignee IS 'Assignee after the accepted change; nullable.';
COMMENT ON COLUMN ktc.punch_item_event.item_version IS 'Version of the punch item after this accepted change.';
COMMENT ON COLUMN ktc.punch_item_event.occurred_at IS 'Database-generated event time with time zone.';
COMMENT ON COLUMN ktc.schema_migration.version IS 'Applied migration number; positive versions are applied in order.';
COMMENT ON COLUMN ktc.schema_migration.description IS 'Short explanation of the migration, at most 200 characters.';
COMMENT ON COLUMN ktc.schema_migration.applied_at IS 'When the migration was successfully applied.';
COMMIT;
